    if (location.pathname === "/staff/sales" || location.pathname === "/staff/operations") { const script = document.createElement("script"); script.src = "/static/web/sales.js?v=20260823"; document.head.appendChild(script); }
    if (location.pathname === "/staff/sales" || location.pathname === "/staff/cash-sales") { const script = document.createElement("script"); script.src = "/static/web/sale-tools.js?v=20260824"; document.head.appendChild(script); }
